SELECT IDProducto, NombreProducto, PrecioUnitario
FROM Productos
WHERE PrecioUnitario > (SELECT AVG(PrecioUnitario) FROM Productos);

SELECT IDTerritorio, DescripcionTerritorio
FROM Territorios
WHERE IDTerritorio NOT IN (SELECT IDTerritorio FROM EmpleadoTerritorios);

SELECT IDProducto, NombreProducto, IDProveedor
FROM Productos
WHERE IDProveedor IN (SELECT IDProveedor FROM Proveedores WHERE Pais = 'Alemania');

SELECT IDCliente, NombreEmpresa
FROM Clientes AS C
WHERE NOT EXISTS (SELECT 1 FROM Pedidos AS P WHERE P.IDCliente = C.IDCliente);

SELECT P.IDPedido, P.EnvioPor, P.Flete
FROM Pedidos AS P
WHERE P.Flete > (
    SELECT AVG(P2.Flete) FROM Pedidos AS P2 WHERE P2.EnvioPor = P.EnvioPor
);

SELECT IDEmpleado, Apellido, Nombre
FROM Empleados AS E
WHERE EXISTS (
    SELECT 1 FROM Pedidos AS P WHERE P.IDEmpleado = E.IDEmpleado AND P.PaisEnvio = 'Mexico'
);

SELECT IDEmpleado, COUNT(*) AS CantidadPedidos
FROM Pedidos
GROUP BY IDEmpleado
HAVING COUNT(*) > (
    SELECT AVG(Cnt) FROM (SELECT COUNT(*) AS Cnt FROM Pedidos GROUP BY IDEmpleado) AS Sub
);

SELECT E.Apellido, T.NombreEmpresa AS Transportista
FROM Empleados AS E
CROSS JOIN Transportistas AS T;

SELECT P.IDPedido, C.NombreEmpresa
FROM Pedidos AS P
INNER JOIN Clientes AS C ON C.IDCliente = P.IDCliente;

CREATE TABLE #RangosPrecio(
    RangoDesde decimal(19,4), RangoHasta decimal(19,4), Etiqueta varchar(20)
);
INSERT INTO #RangosPrecio VALUES
(0, 20, 'Económico'), (20.01, 50, 'Medio'), (50.01, 9999, 'Premium');

SELECT PR.NombreProducto, PR.PrecioUnitario, RP.Etiqueta
FROM Productos AS PR
INNER JOIN #RangosPrecio AS RP
    ON PR.PrecioUnitario BETWEEN RP.RangoDesde AND RP.RangoHasta;

SELECT E.Apellido AS Empleado, J.Apellido AS Jefe
FROM Empleados AS E
LEFT JOIN Empleados AS J ON J.IDEmpleado = E.JefeID;

SELECT C.IDCliente, C.NombreEmpresa, P.IDPedido
FROM Clientes AS C
LEFT OUTER JOIN Pedidos AS P ON P.IDCliente = C.IDCliente;

SELECT C.IDCliente, C.NombreEmpresa, P.IDPedido, E.Apellido
FROM Clientes AS C
LEFT OUTER JOIN (
    Pedidos AS P INNER JOIN Empleados AS E ON E.IDEmpleado = P.IDEmpleado
) ON P.IDCliente = C.IDCliente;

SELECT PV.IDProveedor, PV.NombreEmpresa
FROM Proveedores AS PV
WHERE EXISTS (
    SELECT 1 FROM Productos AS PR WHERE PR.IDProveedor = PV.IDProveedor AND PR.Discontinuado = 1
);

SELECT Ciudad FROM Clientes
UNION
SELECT Ciudad FROM Empleados;

SELECT Ciudad, 'Cliente' AS Origen FROM Clientes
UNION ALL
SELECT Ciudad, 'Empleado' AS Origen FROM Empleados;

SELECT Ciudad FROM Clientes
INTERSECT
SELECT Ciudad FROM Empleados;

SELECT Ciudad FROM Clientes
INTERSECT
SELECT Ciudad FROM Empleados;

SELECT DP.IDPedido, PR.NombreProducto, DP.PrecioUnitario,
       FIRST_VALUE(PR.NombreProducto) OVER (
           PARTITION BY DP.IDPedido ORDER BY DP.PrecioUnitario DESC
       ) AS ProductoMasCaroDelPedido
FROM [Detalles Pedido] AS DP
INNER JOIN Productos AS PR ON PR.IDProducto = DP.IDProducto;

SELECT IDEmpleado, [1] AS [Speedy Express], [2] AS [United Package], [3] AS [Federal Shipping]
FROM (
    SELECT IDEmpleado, EnvioPor FROM Pedidos
) AS Origen
PIVOT (
    COUNT(EnvioPor) FOR EnvioPor IN ([1],[2],[3])
) AS Pvt;

DECLARE @Columnas NVARCHAR(MAX), @SQL NVARCHAR(MAX);

SELECT @Columnas = STRING_AGG(QUOTENAME(NombreCategoria), ',')
FROM Categorias;

SET @SQL = N'
SELECT *
FROM (
    SELECT CAT.NombreCategoria, PR.Discontinuado
    FROM Productos AS PR
    INNER JOIN Categorias AS CAT ON CAT.IDCategoria = PR.IDCategoria
) AS Origen
PIVOT (
    COUNT(Discontinuado) FOR NombreCategoria IN (' + @Columnas + N')
) AS Pvt;';

EXEC sp_executesql @SQL;
